import{_ as l,o as i,c as e,O as r}from"./chunks/framework.db831a78.js";const c=JSON.parse('{"title":"分布式 & 高并发","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/08-分布式高并发.md","filePath":"interview/后端/Java/08-分布式高并发.md","lastUpdated":1787649265000}'),o={name:"interview/后端/Java/08-分布式高并发.md"};function h(t,a,u,d,n,s){return i(),e("div",null,a[0]||(a[0]=[r('<h1 id="分布式-高并发" tabindex="-1">分布式 &amp; 高并发 <a class="header-anchor" href="#分布式-高并发" aria-label="Permalink to &quot;分布式 &amp; 高并发&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解 深度标准：每个考点讲清「是什么 → 为什么 → 追问应对 → 易错点」。</p></blockquote><hr><h2 id="cap-定理与-base-理论-★★★" tabindex="-1">CAP 定理与 BASE 理论 ★★★ <a class="header-anchor" href="#cap-定理与-base-理论-★★★" aria-label="Permalink to &quot;CAP 定理与 BASE 理论 ★★★&quot;">​</a></h2><h3 id="cap" tabindex="-1">CAP <a class="header-anchor" href="#cap" aria-label="Permalink to &quot;CAP&quot;">​</a></h3><ul><li>Consistency（一致性）：所有节点同一时间数据一致。</li><li>Availability（可用性）：每个请求都能得到响应（不保证最新）。</li><li>Partition tolerance（分区容错性）：网络分区时系统仍能工作。</li><li>结论：分布式系统必须保证 P（网络分区不可避免），所以只能在 C 和 A 之间取舍，无法三者兼得。</li></ul><h3 id="base" tabindex="-1">BASE <a class="header-anchor" href="#base" aria-label="Permalink to &quot;BASE&quot;">​</a></h3><ul><li>Basically Available（基本可用）、Soft state（软状态）、Eventually consistent（最终一致）。</li><li>对 CAP 的权衡：不追求强一致，接受最终一致，保证基本可用。</li></ul><h3 id="追问应对" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「CP 和 AP 例子？」→ CP 牺牲可用性保证一致（如 ZooKeeper、etcd、Nacos CP 模式）；AP 牺牲强一致保证可用（如 Eureka、Nacos AP 模式）。</li></ul><hr><h2 id="分布式事务解决方案-★★★" tabindex="-1">分布式事务解决方案 ★★★ <a class="header-anchor" href="#分布式事务解决方案-★★★" aria-label="Permalink to &quot;分布式事务解决方案 ★★★&quot;">​</a></h2><h3 id="为什么需要" tabindex="-1">为什么需要 <a class="header-anchor" href="#为什么需要" aria-label="Permalink to &quot;为什么需要&quot;">​</a></h3><ul><li>单机事务靠数据库本地事务，微服务下跨服务/跨库需分布式事务。</li></ul><h3 id="方案" tabindex="-1">方案 <a class="header-anchor" href="#方案" aria-label="Permalink to &quot;方案&quot;">​</a></h3><ol><li>2PC（两阶段提交）：准备阶段 + 提交阶段；强一致但同步阻塞、协调者单点、性能差。</li><li>TCC（Try-Confirm-Cancel）：业务层三段，Try 预留资源、Confirm 确认、Cancel 取消；灵活但侵入业务、实现复杂。</li><li>SAGA：长事务拆成多个本地事务 + 补偿，适合长流程、高并发；最终一致。</li><li>本地消息表：本地事务 + 消息表，通过消息驱动后续服务，靠定时任务/重试保证最终一致。</li><li>事务消息（RocketMQ 半消息）：先发半消息，本地事务成功后提交，否则回滚。</li><li>最大努力通知：尽力通知，配合对账/人工兜底。</li></ol><h3 id="中间件" tabindex="-1">中间件 <a class="header-anchor" href="#中间件" aria-label="Permalink to &quot;中间件&quot;">​</a></h3><ul><li>Seata：AT（自动，无侵入，基于 undo log + 全局锁）、TCC、SAGA、XA 模式。</li></ul><h3 id="追问应对-1" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-1" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「2PC 有什么问题？」→ 同步阻塞、协调者单点故障、数据不一致风险。</li><li>「Seata AT 模式原理？」→ 全局事务协调 + 各服务本地事务 + undo log 回滚 + 全局锁防脏写。</li></ul><hr><h2 id="分布式-id-生成-★★★" tabindex="-1">分布式 ID 生成 ★★★ <a class="header-anchor" href="#分布式-id-生成-★★★" aria-label="Permalink to &quot;分布式 ID 生成 ★★★&quot;">​</a></h2><h3 id="方案对比" tabindex="-1">方案对比 <a class="header-anchor" href="#方案对比" aria-label="Permalink to &quot;方案对比&quot;">​</a></h3><ul><li>UUID：本地生成、简单，但无序（不适合做数据库主键，导致页分裂）、过长。</li><li>数据库自增：简单但单点、性能瓶颈，不适合分布式。</li><li>号段模式（如 Leaf）：从数据库批量取一段 id 缓存，减少访问。</li><li>雪花算法（Snowflake）：时间戳 + 机器 id + 序列号，趋势递增、高性能，主流。</li></ul><h3 id="雪花算法" tabindex="-1">雪花算法 <a class="header-anchor" href="#雪花算法" aria-label="Permalink to &quot;雪花算法&quot;">​</a></h3><ul><li>结构：1 位符号 + 41 位时间戳 + 10 位机器 id + 12 位序列号。</li><li>优点：本地生成、趋势递增、高性能；缺点：依赖时钟，时钟回拨会导致重复 id（需处理）。</li></ul><h3 id="追问应对-2" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-2" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「时钟回拨怎么处理？」→ 等待时钟追上、抛异常、用备用机器 id、记录上次时间戳。</li></ul><hr><h2 id="限流算法-令牌桶、漏桶、滑动窗口-★★★" tabindex="-1">限流算法：令牌桶、漏桶、滑动窗口 ★★★ <a class="header-anchor" href="#限流算法-令牌桶、漏桶、滑动窗口-★★★" aria-label="Permalink to &quot;限流算法：令牌桶、漏桶、滑动窗口 ★★★&quot;">​</a></h2><h3 id="算法" tabindex="-1">算法 <a class="header-anchor" href="#算法" aria-label="Permalink to &quot;算法&quot;">​</a></h3><ul><li>固定窗口计数器：一段时间内限固定次数；边界问题（窗口临界突发）。</li><li>滑动窗口：细分窗口平滑，解决固定窗口边界问题。</li><li>漏桶：固定速率流出，能限制平均速率，但无法应对突发（超出即丢弃）。</li><li>令牌桶：固定速率放令牌，桶满停止；能允许一定突发（有令牌即可）。</li></ul><h3 id="选择" tabindex="-1">选择 <a class="header-anchor" href="#选择" aria-label="Permalink to &quot;选择&quot;">​</a></h3><ul><li>令牌桶允许突发，适合大多数 API 限流；漏桶严格平滑，适合需要恒定速率的场景。</li></ul><h3 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h3><ul><li>Sentinel、Guava RateLimiter（令牌桶）、Redis + Lua 脚本、网关限流。</li></ul><h3 id="追问应对-3" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-3" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「令牌桶和漏桶区别？」→ 令牌桶允许突发流量，漏桶严格匀速。</li></ul><hr><h2 id="熔断、降级、隔离-★★★" tabindex="-1">熔断、降级、隔离 ★★★ <a class="header-anchor" href="#熔断、降级、隔离-★★★" aria-label="Permalink to &quot;熔断、降级、隔离 ★★★&quot;">​</a></h2><ul><li>熔断：依赖服务异常比例超阈值时，直接返回兜底，快速失败，防止级联故障（断路器：关闭→打开→半开）。</li><li>降级：系统压力大时，关闭非核心功能，保核心链路。</li><li>隔离：线程池/信号量隔离，防止某个依赖占满资源拖垮整体（Hystrix 线程池隔离）。</li></ul><h3 id="工具-1" tabindex="-1">工具 <a class="header-anchor" href="#工具-1" aria-label="Permalink to &quot;工具&quot;">​</a></h3><ul><li>Sentinel、Resilience4j、Hystrix（已停维护）。</li></ul><h3 id="追问应对-4" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-4" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「熔断和降级区别？」→ 熔断是「被动应对依赖故障」，降级是「主动关功能保核心」。</li></ul><hr><h2 id="接口幂等性-★★★" tabindex="-1">接口幂等性 ★★★ <a class="header-anchor" href="#接口幂等性-★★★" aria-label="Permalink to &quot;接口幂等性 ★★★&quot;">​</a></h2><h3 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h3><ul><li>网络重试、用户重复点击、消息重复投递导致重复请求，需保证重复执行结果一致。</li></ul><h3 id="方案-1" tabindex="-1">方案 <a class="header-anchor" href="#方案-1" aria-label="Permalink to &quot;方案&quot;">​</a></h3><ul><li>唯一索引：数据库唯一约束，重复插入失败。</li><li>Token 机制：提交前先获取 token，提交时校验并删除 token（防重复提交）。</li><li>状态机：只有特定状态能流转（如待支付→已支付）。</li><li>乐观锁：版本号/条件更新。</li><li>Redis 分布式锁 / setnx。</li></ul><h3 id="追问应对-5" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-5" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「哪些操作天然幂等？」→ 查询、删除（按 id）、更新（绝对值）；非幂等如「余额 += 100」。</li></ul><hr><h2 id="一致性哈希-★★★" tabindex="-1">一致性哈希 ★★★ <a class="header-anchor" href="#一致性哈希-★★★" aria-label="Permalink to &quot;一致性哈希 ★★★&quot;">​</a></h2><h3 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h3><ul><li>把节点和 key 都哈希到同一个环上，key 顺时针找到的第一个节点就是它归属的节点。</li><li>节点增删时，只影响相邻的一小段数据，最小化迁移。</li></ul><h3 id="虚拟节点" tabindex="-1">虚拟节点 <a class="header-anchor" href="#虚拟节点" aria-label="Permalink to &quot;虚拟节点&quot;">​</a></h3><ul><li>每个真实节点映射多个虚拟节点，解决数据倾斜和分布不均。</li></ul><h3 id="应用" tabindex="-1">应用 <a class="header-anchor" href="#应用" aria-label="Permalink to &quot;应用&quot;">​</a></h3><ul><li>分布式缓存分片（如 Memcached 客户端）、负载均衡、数据分片。</li></ul><h3 id="追问应对-6" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-6" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「一致性哈希 vs 普通哈希取模？」→ 取模在节点数变化时几乎所有 key 都要重新映射；一致性哈希只迁移少部分。</li></ul><hr><h2 id="高并发场景-秒杀系统设计-★★★" tabindex="-1">高并发场景：秒杀系统设计 ★★★ <a class="header-anchor" href="#高并发场景-秒杀系统设计-★★★" aria-label="Permalink to &quot;高并发场景：秒杀系统设计 ★★★&quot;">​</a></h2><h3 id="核心问题与方案" tabindex="-1">核心问题与方案 <a class="header-anchor" href="#核心问题与方案" aria-label="Permalink to &quot;核心问题与方案&quot;">​</a></h3><ol><li>高并发读/写 → 前端限流、CDN 缓存、Nginx 限流、Redis 预扣库存。</li><li>超卖 → Redis 原子扣减（decr/lua）、数据库乐观锁（<code>update ... where stock &gt; 0</code>）。</li><li>流量洪峰 → 消息队列削峰、令牌桶限流。</li><li>数据库压力 → 读写分离、分库分表。</li><li>防黄牛 → 验证码、限购（一人一单）、风控。</li><li>数据一致性 → 库存扣减 + 订单 + 异步消息 + 补偿。</li></ol><h3 id="完整链路" tabindex="-1">完整链路 <a class="header-anchor" href="#完整链路" aria-label="Permalink to &quot;完整链路&quot;">​</a></h3><ul><li>用户点击 → CDN/静态页 → 网关限流 → 秒杀接口 → Redis 预扣库存（原子）→ 消息队列 → 生成订单 → 数据库落库 → 异步扣真实库存。</li></ul><h3 id="追问应对-7" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-7" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「怎么防超卖？」→ Redis 原子扣减 + 数据库乐观锁/唯一索引兜底。</li><li>「热点商品怎么处理？」→ 本地缓存 + Redis 集群 + 分桶/多副本分流。</li></ul><hr><h2 id="分布式锁的实现与问题-★★★" tabindex="-1">分布式锁的实现与问题 ★★★ <a class="header-anchor" href="#分布式锁的实现与问题-★★★" aria-label="Permalink to &quot;分布式锁的实现与问题 ★★★&quot;">​</a></h2><ul><li>见中间件 Redis 部分：SET NX EX + Lua 释放 + 看门狗续期。</li><li>其他：ZooKeeper 临时顺序节点（watch 机制，羊群效应）、数据库唯一索引。</li></ul><h3 id="追问应对-8" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-8" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「Redis 和 ZK 分布式锁区别？」→ Redis 基于过期时间 + 续期，性能高但主从切换可能丢锁；ZK 基于临时节点，强一致但性能较低。</li></ul><hr><h2 id="服务治理-注册发现、配置中心、网关-★★★" tabindex="-1">服务治理：注册发现、配置中心、网关 ★★★ <a class="header-anchor" href="#服务治理-注册发现、配置中心、网关-★★★" aria-label="Permalink to &quot;服务治理：注册发现、配置中心、网关 ★★★&quot;">​</a></h2><ul><li>注册发现：服务启动注册到注册中心（Nacos/Eureka），调用方从注册中心拉取实例列表，配合负载均衡。</li><li>配置中心：集中管理配置，动态刷新（Nacos Config）。</li><li>网关：统一入口、路由、鉴权、限流、灰度。</li></ul><h3 id="追问应对-9" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-9" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「服务发现怎么实现？」→ 服务注册 + 心跳续约 + 拉取服务列表 + 负载均衡调用。</li></ul><hr><h2 id="分布式链路追踪-★★☆" tabindex="-1">分布式链路追踪 ★★☆ <a class="header-anchor" href="#分布式链路追踪-★★☆" aria-label="Permalink to &quot;分布式链路追踪 ★★☆&quot;">​</a></h2><ul><li>目的：定位跨服务调用链、性能瓶颈、故障。</li><li>方案：SkyWalking、Zipkin、Jaeger。</li><li>核心：traceId 贯穿整条链路，span 表示一次调用。</li></ul><h3 id="追问应对-10" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-10" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「traceId 怎么传递？」→ 通过请求头（如 X-Trace-Id）透传，各服务日志记录。</li></ul><hr><h2 id="高并发下的数据一致性-缓存双写、读写分离-★★☆" tabindex="-1">高并发下的数据一致性：缓存双写、读写分离 ★★☆ <a class="header-anchor" href="#高并发下的数据一致性-缓存双写、读写分离-★★☆" aria-label="Permalink to &quot;高并发下的数据一致性：缓存双写、读写分离 ★★☆&quot;">​</a></h2><ul><li>缓存双写一致性：见中间件篇（Cache Aside + 延迟双删 + binlog 订阅）。</li><li>读写分离：主写从读，注意主从延迟（实时性要求高的读走主库）。</li></ul><hr><h2 id="幂等-分布式锁-限流在订单场景的综合运用-★★☆" tabindex="-1">幂等 + 分布式锁 + 限流在订单场景的综合运用 ★★☆ <a class="header-anchor" href="#幂等-分布式锁-限流在订单场景的综合运用-★★☆" aria-label="Permalink to &quot;幂等 + 分布式锁 + 限流在订单场景的综合运用 ★★☆&quot;">​</a></h2><ul><li>下单流程：限流（防刷）→ 幂等（防重复提交）→ 分布式锁（防并发扣减）→ 库存扣减（乐观锁）→ 生成订单 → 消息通知。</li><li>体现：多个手段叠加保证高并发下的正确性与可用性。</li></ul><hr><h2 id="亿级黑名单快速定位-url-★★★" tabindex="-1">亿级黑名单快速定位 URL ★★★ <a class="header-anchor" href="#亿级黑名单快速定位-url-★★★" aria-label="Permalink to &quot;亿级黑名单快速定位 URL ★★★&quot;">​</a></h2><h3 id="核心" tabindex="-1">核心 <a class="header-anchor" href="#核心" aria-label="Permalink to &quot;核心&quot;">​</a></h3><ul><li>用布隆过滤器（Bloom Filter）判断「某个 URL 是否可能在黑名单中」。</li></ul><h3 id="布隆过滤器原理" tabindex="-1">布隆过滤器原理 <a class="header-anchor" href="#布隆过滤器原理" aria-label="Permalink to &quot;布隆过滤器原理&quot;">​</a></h3><ul><li>一个 m 位比特数组 + k 个哈希函数。</li><li>加入元素：用 k 个哈希函数算 k 个位置，都置 1。</li><li>查询元素：算 k 个位置，若都为 1 → 「可能存在」（可能误判）；若任一为 0 → 「一定不存在」。</li><li>特点：省空间（亿级只需几百 MB）、快（O(k)）；有误判率（可通过增大 m、增多 k 降低），不支持删除。</li></ul><h3 id="为什么用布隆过滤器" tabindex="-1">为什么用布隆过滤器 <a class="header-anchor" href="#为什么用布隆过滤器" aria-label="Permalink to &quot;为什么用布隆过滤器&quot;">​</a></h3><ul><li>亿级黑名单存内存全量 set 太大；布隆过滤器用极小空间做到「一定不存在」快速拦截，只对「可能存在」的少量再查真实库确认。</li></ul><h3 id="追问应对-11" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-11" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「布隆过滤器有误判怎么处理？」→ 只做第一层拦截，命中的再去数据库/精确集合二次确认。</li><li>「怎么选 m 和 k？」→ 根据数据量和可接受误判率计算；误判率越低 m 越大、k 越接近最优值。</li><li>「布隆过滤器支持删除吗？」→ 不支持，需用计数布隆（Counting Bloom）或定期重建。</li></ul><hr><h2 id="设计短网址系统-★★★" tabindex="-1">设计短网址系统 ★★★ <a class="header-anchor" href="#设计短网址系统-★★★" aria-label="Permalink to &quot;设计短网址系统 ★★★&quot;">​</a></h2><h3 id="需求" tabindex="-1">需求 <a class="header-anchor" href="#需求" aria-label="Permalink to &quot;需求&quot;">​</a></h3><ul><li>长 URL → 短码（如 t.cn/ab3f）；短码 → 重定向到长 URL。</li></ul><h3 id="核心设计" tabindex="-1">核心设计 <a class="header-anchor" href="#核心设计" aria-label="Permalink to &quot;核心设计&quot;">​</a></h3><ol><li>短码生成：对长 URL 生成唯一短码，可选： <ul><li>哈希 + 截断（MD5/Base62 取 6-7 位），冲突则加盐重试。</li><li>发号器（自增 id → Base62 编码），无冲突，推荐。</li></ul></li><li>存储：短码 → 长 URL 的映射，存 MySQL/Redis（短码做唯一索引，长 URL 可哈希判重）。</li><li>访问：302 重定向到长 URL；热点短链缓存到 Redis/CDN。</li><li>高并发读：读多写少，用缓存扛读；写用号段/雪花 id 生成短码。</li></ol><h3 id="追问应对-12" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-12" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「短码会不会重复？」→ 发号器保证唯一；哈希方案需判重处理冲突。</li><li>「为什么用 302 不用 301？」→ 302 临时重定向，保留统计点击能力；301 永久重定向浏览器会缓存，后续不经过服务器。</li></ul><hr><h2 id="限时订单设计-★★★" tabindex="-1">限时订单设计 ★★★ <a class="header-anchor" href="#限时订单设计-★★★" aria-label="Permalink to &quot;限时订单设计 ★★★&quot;">​</a></h2><h3 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><ul><li>订单创建后限时（如 30 分钟）未支付则自动取消，释放库存。</li></ul><h3 id="核心方案" tabindex="-1">核心方案 <a class="header-anchor" href="#核心方案" aria-label="Permalink to &quot;核心方案&quot;">​</a></h3><ul><li>延迟消息：RocketMQ 延迟消息 / RabbitMQ 死信 + TTL，下单后发一条延迟 30 分钟的消息，到点消费检查订单状态，未支付则取消。</li><li>定时任务扫描：定时扫描「超时未支付」订单批量取消（简单但有时延、压力）。</li><li>Redis 过期 key + 过期监听：下单设 key 过期 30 分钟，监听过期事件取消（有精度/可靠性问题，慎用）。</li></ul><h3 id="关键点" tabindex="-1">关键点 <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点&quot;">​</a></h3><ul><li>幂等：取消操作要幂等（可能被重复触发）。</li><li>库存回补：取消订单要回补库存（注意与并发扣减的一致性）。</li><li>状态机：订单状态「待支付 → 已取消/已支付」，只有待支付才能取消。</li></ul><h3 id="追问应对-13" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-13" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么用延迟消息而不是轮询？」→ 延迟消息精确到点、不额外扫库、解耦；轮询有时延和扫描压力。</li></ul><hr><h2 id="设计高并发支付网关-★★★" tabindex="-1">设计高并发支付网关 ★★★ <a class="header-anchor" href="#设计高并发支付网关-★★★" aria-label="Permalink to &quot;设计高并发支付网关 ★★★&quot;">​</a></h2><h3 id="关注点" tabindex="-1">关注点 <a class="header-anchor" href="#关注点" aria-label="Permalink to &quot;关注点&quot;">​</a></h3><ol><li>安全：签名/验签、加密、防篡改、防重放（时间戳 + nonce）、防重复支付（幂等）。</li><li>高可用：多机房/多节点、限流、熔断降级、集群。</li><li>一致性：支付结果与订单状态一致（对账、回调、主动查询兜底）。</li><li>幂等：同一笔订单不能重复扣款（订单号 + 唯一约束 + 分布式锁）。</li><li>异步通知：支付回调用 MQ 异步处理，失败重试。</li><li>对账：定时与渠道对账，处理掉单/差错账。</li><li>状态机：订单支付状态严格流转。</li></ol><h3 id="追问应对-14" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-14" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「支付回调丢了怎么办？」→ 主动查询兜底（定时查渠道支付结果）+ 重试 + 对账。</li><li>「怎么防重复支付？」→ 幂等（订单号唯一、状态机、分布式锁）。</li></ul><hr><h2 id="设计打车服务-★★☆" tabindex="-1">设计打车服务 ★★☆ <a class="header-anchor" href="#设计打车服务-★★☆" aria-label="Permalink to &quot;设计打车服务 ★★☆&quot;">​</a></h2><h3 id="关注点-1" tabindex="-1">关注点 <a class="header-anchor" href="#关注点-1" aria-label="Permalink to &quot;关注点&quot;">​</a></h3><ul><li>位置存储与检索：乘客/司机位置用地理位置索引（GeoHash/空间索引）。</li><li>匹配：按距离/评分派单，用 Redis GEO 或地理索引查询附近司机。</li><li>状态机：订单（呼叫→接单→上车→行程中→完成→支付）。</li><li>实时性：司机位置上报（WebSocket/MQ 削峰）、轨迹存储。</li><li>高并发：地理查询压力大，用缓存/分区/索引优化。</li><li>一致性：派单防重复（分布式锁/状态机）。</li></ul><h3 id="追问应对-15" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-15" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「怎么找附近司机？」→ 用 GeoHash 把经纬度编码，相近位置 hash 前缀相同，按前缀查附近司机。</li></ul><hr><h2 id="设计视频流系统-★★☆" tabindex="-1">设计视频流系统 ★★☆ <a class="header-anchor" href="#设计视频流系统-★★☆" aria-label="Permalink to &quot;设计视频流系统 ★★☆&quot;">​</a></h2><h3 id="关注点-2" tabindex="-1">关注点 <a class="header-anchor" href="#关注点-2" aria-label="Permalink to &quot;关注点&quot;">​</a></h3><ul><li>存储：视频对象存储（OSS/S3）+ CDN 分发。</li><li>上传：分片上传、转码（多码率）、鉴黄审核。</li><li>播放：CDN 加速、断点续传、自适应码率（HLS/DASH）。</li><li>元数据：视频信息、评论、点赞存数据库，读多用缓存。</li><li>高并发读：CDN + 缓存扛住读流量。</li></ul><h3 id="追问应对-16" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-16" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「视频为什么用 CDN？」→ 就近分发、减轻源站压力、降低延迟。</li><li>「为什么要转码？」→ 适配不同网络/设备的多码率，降低带宽、提升播放体验。</li></ul><hr><h2 id="实时统计日-周-月活跃用户-dau-wau-mau-★★★" tabindex="-1">实时统计日/周/月活跃用户（DAU/WAU/MAU）★★★ <a class="header-anchor" href="#实时统计日-周-月活跃用户-dau-wau-mau-★★★" aria-label="Permalink to &quot;实时统计日/周/月活跃用户（DAU/WAU/MAU）★★★&quot;">​</a></h2><h3 id="方案-2" tabindex="-1">方案 <a class="header-anchor" href="#方案-2" aria-label="Permalink to &quot;方案&quot;">​</a></h3><ul><li>Redis Bitmap：一个用户一个 bit 位，<code>setbit</code> 记录当日活跃，按位统计去重活跃数（<code>bitcount</code>）。 <ul><li>日活：每天一个 bitmap；周活/月活：对多天 bitmap 做 <code>bitop OR</code> 求并集再 bitcount。</li></ul></li><li>优点：省内存（1 亿用户约 12MB）、去重、位运算快。</li></ul><h3 id="追问应对-17" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-17" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「Bitmap 适合什么场景？」→ 用户 id 连续或可映射成连续整数的去重统计；稀疏数据用 HyperLogLog。</li></ul><hr><h2 id="统计高并发网站每个网页每天-uv-★★★" tabindex="-1">统计高并发网站每个网页每天 UV ★★★ <a class="header-anchor" href="#统计高并发网站每个网页每天-uv-★★★" aria-label="Permalink to &quot;统计高并发网站每个网页每天 UV ★★★&quot;">​</a></h2><h3 id="方案-3" tabindex="-1">方案 <a class="header-anchor" href="#方案-3" aria-label="Permalink to &quot;方案&quot;">​</a></h3><ul><li>HyperLogLog（HLL）：概率数据结构，用极小内存（约 12KB/键）统计独立元素个数（UV）。</li><li>每个网页每天一个 HLL 键，<code>pfadd</code> 记录访客 id，<code>pfcount</code> 得到 UV（有约 0.81% 误差）。</li><li>相比 set：set 精确但内存大（UV 多时爆内存），HLL 用固定小内存换近似值。</li></ul><h3 id="追问应对-18" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-18" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「HLL 和 Bitmap 区别？」→ Bitmap 精确但内存与最大 id 成正比；HLL 近似、固定小内存、适合超大去重统计。</li><li>「HLL 为什么有误差？」→ 基于哈希 + 概率统计，用固定桶近似基数，标准误差约 0.81%。</li></ul><hr><h2 id="_10-亿数量高效排序-★★☆" tabindex="-1">10 亿数量高效排序 ★★☆ <a class="header-anchor" href="#_10-亿数量高效排序-★★☆" aria-label="Permalink to &quot;10 亿数量高效排序 ★★☆&quot;">​</a></h2><h3 id="核心-外部排序" tabindex="-1">核心：外部排序 <a class="header-anchor" href="#核心-外部排序" aria-label="Permalink to &quot;核心：外部排序&quot;">​</a></h3><ul><li>数据量大无法一次性载入内存，用「外部归并排序」： <ol><li>把大数据分成能装进内存的小块，每块内部排序后落盘（生成多个有序子文件）。</li><li>用多路归并，把多个有序子文件合并成一个大有序文件（用堆维护每路当前最小值）。</li></ol></li><li>分治 + 归并，内存占用可控，磁盘 IO 是瓶颈。</li></ul><h3 id="追问应对-19" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-19" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么不能直接内存排序？」→ 10 亿数据超内存，需外部排序。</li><li>「怎么加速？」→ 增加内存块大小、多路归并、并行处理、分布式（MapReduce/Spark 外部排序）。</li></ul><hr><h2 id="为什么要进行系统拆分-如何拆分-★★★" tabindex="-1">为什么要进行系统拆分，如何拆分 ★★★ <a class="header-anchor" href="#为什么要进行系统拆分-如何拆分-★★★" aria-label="Permalink to &quot;为什么要进行系统拆分，如何拆分 ★★★&quot;">​</a></h2><h3 id="为什么拆分" tabindex="-1">为什么拆分 <a class="header-anchor" href="#为什么拆分" aria-label="Permalink to &quot;为什么拆分&quot;">​</a></h3><ul><li>单体会随业务增长变得臃肿：编译部署慢、代码耦合、团队协作冲突、故障影响面大、难以独立扩容。</li><li>拆分后：独立部署、独立扩展、故障隔离、团队自治、技术栈灵活。</li></ul><h3 id="如何拆分" tabindex="-1">如何拆分 <a class="header-anchor" href="#如何拆分" aria-label="Permalink to &quot;如何拆分&quot;">​</a></h3><ol><li>按业务域拆分：先识别核心领域（用户、订单、商品、支付、库存等），按「高内聚、低耦合」拆成独立服务（可参考 DDD 限界上下文）。</li><li>拆分顺序：先拆边缘/独立性强的服务，再拆核心服务；先拆读多写少、耦合低的。</li><li>数据库拆分：每个服务独立数据库，避免跨服务直接 join，数据通过接口/消息交互。</li><li>配套治理：注册中心、配置中心、网关、服务调用（RPC）、链路追踪、熔断限流。</li></ol><h3 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h3><ul><li>别过度拆分：拆太细导致分布式复杂度（网络、一致性、运维）剧增；小规模先单体，业务/团队到了一定规模再拆。</li></ul><h3 id="追问应对-20" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-20" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「拆分后分布式事务怎么办？」→ 用最终一致（本地消息表/TCC/SAGA/事务消息），不强求跨服务强一致。</li></ul><hr><h2 id="如何设计一个类似-dubbo-的-rpc-框架-★★★" tabindex="-1">如何设计一个类似 Dubbo 的 RPC 框架 ★★★ <a class="header-anchor" href="#如何设计一个类似-dubbo-的-rpc-框架-★★★" aria-label="Permalink to &quot;如何设计一个类似 Dubbo 的 RPC 框架 ★★★&quot;">​</a></h2><h3 id="核心组成" tabindex="-1">核心组成 <a class="header-anchor" href="#核心组成" aria-label="Permalink to &quot;核心组成&quot;">​</a></h3><ol><li>服务发现：注册中心（服务注册/订阅/心跳）。</li><li>代理：客户端生成接口动态代理，屏蔽远程调用细节。</li><li>序列化：请求/响应对象序列化（Hessian、Protobuf、JSON）。</li><li>网络通信：高性能传输（Netty），自定义协议（报文头：魔数、长度、序列化方式、请求 id）。</li><li>负载均衡：多个服务实例间选择（随机、轮询、加权、最小连接、一致性哈希）。</li><li>容错：超时、重试、熔断、降级。</li><li>服务治理：路由、灰度、限流、监控、链路追踪。</li></ol><h3 id="调用流程" tabindex="-1">调用流程 <a class="header-anchor" href="#调用流程" aria-label="Permalink to &quot;调用流程&quot;">​</a></h3><ul><li>客户端调用接口 → 动态代理拦截 → 从注册中心选一个服务实例 → 序列化请求 → 网络发送 → 服务端反序列化 → 反射调用实现 → 序列化响应 → 返回客户端。</li></ul><h3 id="追问应对-21" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-21" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「RPC 和 HTTP 区别？」→ RPC 是自定义协议、二进制序列化、基于长连接/连接池，性能更高、更适合内部服务调用；HTTP 通用、跨语言、易调试，适合对外接口。</li></ul><hr><h2 id="dubbo-的工作原理-★★☆" tabindex="-1">Dubbo 的工作原理 ★★☆ <a class="header-anchor" href="#dubbo-的工作原理-★★☆" aria-label="Permalink to &quot;Dubbo 的工作原理 ★★☆&quot;">​</a></h2><h3 id="核心角色" tabindex="-1">核心角色 <a class="header-anchor" href="#核心角色" aria-label="Permalink to &quot;核心角色&quot;">​</a></h3><ul><li>Provider（服务提供者）、Consumer（服务消费者）、Registry（注册中心，如 Zookeeper/Nacos）、Monitor（监控）。</li><li>流程：Provider 启动注册到注册中心 → Consumer 订阅并缓存服务列表 → Consumer 按负载均衡选实例 → 发起远程调用（Netty）→ 服务端执行并返回。</li></ul><h3 id="调用链路" tabindex="-1">调用链路 <a class="header-anchor" href="#调用链路" aria-label="Permalink to &quot;调用链路&quot;">​</a></h3><ul><li>客户端代理 → 集群容错（重试/失败切换）→ 负载均衡 → 协议编解码 → 网络传输 → 服务端过滤链 → 反射调用实现。</li></ul><h3 id="追问应对-22" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-22" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「注册中心挂了 Dubbo 还能调用吗？」→ 能，Consumer 本地有缓存的服务列表，可继续用本地缓存调用（只是新实例变化感知不到）。</li></ul><hr><h2 id="dubbo-负载均衡策略-★★☆" tabindex="-1">Dubbo 负载均衡策略 ★★☆ <a class="header-anchor" href="#dubbo-负载均衡策略-★★☆" aria-label="Permalink to &quot;Dubbo 负载均衡策略 ★★☆&quot;">​</a></h2><ul><li>Random（随机，默认）：按权重随机。</li><li>RoundRobin（轮询）：按权重轮询。</li><li>LeastActive（最少活跃数）：选当前活跃请求最少的实例。</li><li>ConsistentHash（一致性哈希）：同一参数/请求路由到同一实例（会话粘性）。</li><li>可自定义实现 LoadBalance 接口。</li></ul><h3 id="追问应对-23" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-23" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「一致性哈希负载均衡适合什么？」→ 需要同一请求打到同一台机器的场景（如缓存、会话保持）。</li></ul><hr><h2 id="dubbo-服务治理、服务降级-★★☆" tabindex="-1">Dubbo 服务治理、服务降级 ★★☆ <a class="header-anchor" href="#dubbo-服务治理、服务降级-★★☆" aria-label="Permalink to &quot;Dubbo 服务治理、服务降级 ★★☆&quot;">​</a></h2><ul><li>服务治理：路由规则、灰度发布、权重调整、限流、熔断、监控、链路追踪。</li><li>服务降级：依赖服务不可用/超时时，返回兜底结果（mock/容错）。</li><li>容错策略：Failover（失败重试，默认）、Failfast（快速失败）、Failsafe（忽略异常）、Failback（失败记录后定时重发）、Forking（并行调用多实例）。</li></ul><h3 id="追问应对-24" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-24" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「Dubbo 怎么做熔断限流？」→ 可集成 Sentinel/Hystrix，或自定义 Filter 实现。</li></ul><hr><h2 id="dubbo-spi-和-java-spi-的区别-★★☆" tabindex="-1">Dubbo SPI 和 Java SPI 的区别 ★★☆ <a class="header-anchor" href="#dubbo-spi-和-java-spi-的区别-★★☆" aria-label="Permalink to &quot;Dubbo SPI 和 Java SPI 的区别 ★★☆&quot;">​</a></h2><h3 id="java-spi" tabindex="-1">Java SPI <a class="header-anchor" href="#java-spi" aria-label="Permalink to &quot;Java SPI&quot;">​</a></h3><ul><li>通过 <code>META-INF/services/接口全限定名</code> 文件列出实现类，<code>ServiceLoader</code> 加载。</li><li>缺点：一次性加载所有实现（不能按需）、不支持按名获取、扩展点不够灵活。</li></ul><h3 id="dubbo-spi" tabindex="-1">Dubbo SPI <a class="header-anchor" href="#dubbo-spi" aria-label="Permalink to &quot;Dubbo SPI&quot;">​</a></h3><ul><li>通过 <code>META-INF/dubbo/</code> 目录配置，用「key=实现类」形式。</li><li>支持按 name 精确获取（<code>ExtensionLoader.getExtension(&quot;name&quot;)</code>）、支持默认实现、自适应扩展（@Adaptive）、包装/激活（Wrapper、Activate）、按需加载。</li><li>是 Dubbo 扩展机制的核心。</li></ul><h3 id="追问应对-25" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-25" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「Dubbo SPI 为什么比 Java SPI 强？」→ 支持按 key 获取、懒加载、默认值、自适应、依赖注入，灵活度和性能都更好。</li></ul><hr><h2 id="为什么做分库分表-业务侧-★★☆" tabindex="-1">为什么做分库分表（业务侧）★★☆ <a class="header-anchor" href="#为什么做分库分表-业务侧-★★☆" aria-label="Permalink to &quot;为什么做分库分表（业务侧）★★☆&quot;">​</a></h2><ul><li>单表数据量过大（千万级+）：查询变慢、索引维护开销大、DDL 变慢。</li><li>单库连接数、容量、IO 达到瓶颈，无法横向扩展。</li><li>写多读多，单库扛不住高并发。</li><li>分库分表实现横向扩展：分片后每个库/表数据量变小，读写压力分散。</li></ul><h3 id="追问应对-26" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-26" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「分库分表一定好吗？」→ 不是，引入分布式事务、跨库 join、分布式主键、路由等复杂度；先做索引优化、缓存、读写分离，仍不够再分。</li></ul>',205)]))}const q=l(o,[["render",h]]);export{c as __pageData,q as default};
